1	/**
2	 * The `install` stage: resolve the lane's own closure, under declared policy.
3	 *
4	 * Spike C measured two npm decisions on the first unseen application and named
5	 * them as manual residue: "Two operator decisions per application before the
6	 * first build. Both are mechanisable as policy, and both are today unwritten
7	 * judgment" (`evidence/spikes/thin-wrapper-cost/verdict.json`, finding C3). The
8	 * first was a 2020 lockfile carrying an `https` tarball dependency, which modern
9	 * npm refuses with `EALLOWREMOTE`; the second was install scripts, which modern
10	 * npm skips by default, so the tree installed "without its native build ever
11	 * being attempted".
12	 *
13	 * Both are policies here, not judgment. Each has a declared flag, each defaults
14	 * to *not applied*, and a closure that needs one it was not given is a named
15	 * refusal rather than an operator reading a wall of npm output and deciding. The
16	 * defaults are the honest ones: this flow does not widen a package manager's own
17	 * safety default on an operator's behalf, and it does not install a tree whose
18	 * native build was silently skipped and call it installed.
19	 *
20	 * The policy findings are read out of the lockfile before anything runs, so the
21	 * refusal arrives before the network is touched rather than after a failed
22	 * install.
23	 */
24	
25	import { execFile } from 'node:child_process';
26	import { mkdir, readFile, readdir } from 'node:fs/promises';
27	import { promisify } from 'node:util';
28	import * as path from 'pathe';
29	import { parseURL } from 'ufo';
30	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
31	import { directoryExists, fileExists, readJsonFile } from './analyze.ts';
32	import { refuse } from './refusals.ts';
33	
34	const run = promisify(execFile);
35	
36	/** The registry npm resolves a plain dependency from. */
37	export const DEFAULT_REGISTRY_HOST = 'registry.npmjs.org';
38	
39	/** The lockfiles this stage can install from, in the order it looks for them. */
40	export const NPM_LOCKFILES: readonly string[] = Object.freeze([
41		'package-lock.json',
42		'npm-shrinkwrap.json',
43	]);
44	
45	/** Lockfiles that name a package manager this stage's policies do not cover. */
46	export const FOREIGN_LOCKFILES: Readonly<Record<string, string>> = Object.freeze({
47		'bun.lockb': 'bun',
48		'yarn.lock': 'yarn',
49		'pnpm-lock.yaml': 'pnpm',
50	});
51	
52	export type InstallPolicy = Readonly<{
53		/** Carry npm's `--allow-remote` allowance for non-registry tarballs. */
54		allowRemoteTarballs: boolean;
55		/** Run the closure's install scripts, so a native build is attempted. */
56		allowInstallScripts: boolean;
57		/** Skip them, as a declared decision rather than as npm's silent default. */
58		skipInstallScripts: boolean;
59		/**
60		 * Install through a peer-dependency conflict.
61		 *
62		 * The third policy, and the one this repository measured rather than
63		 * inherited: a lane whose manifest now declares a current build toolchain
64		 * beside an era application's own pins can fail npm's peer resolution
65		 * outright (`ERESOLVE`). Carrying the allowance is a decision about what the
66		 * lane's closure is allowed to be, so it is declared like the other two.
67		 */
68		allowPeerConflicts: boolean;
69	}>;
70	
71	export const DEFAULT_INSTALL_POLICY: InstallPolicy = Object.freeze({
72		allowRemoteTarballs: false,
73		allowInstallScripts: false,
74		skipInstallScripts: false,
75		allowPeerConflicts: false,
76	});
77	
78	export type LockfileFindings = Readonly<{
79		lockfile: string;
80		lockfileVersion: number;
81		/** Dependencies resolved from somewhere other than the npm registry. */
82		remoteTarballDependencies: readonly string[];
83		/** Packages the lockfile marks as carrying an install script. */
84		installScriptPackages: readonly string[];
85	}>;
86	
87	const INSTALL_NOT_ESTABLISHED: readonly string[] = Object.freeze([
88		'An install resolves a closure. It is not a build, and it is not evidence that the closure works: nothing here establishes that any package in it compiles or runs.',
89		'The policy findings are read from the lockfile. A lockfile that does not mark an install script, or that resolves through a mirror this reading does not recognise, yields a finding this stage did not make.',
90		'`installScriptPackages` counts packages the lockfile declares an install script for. Whether a given script would have built anything on this host is not established here.',
91		'The sandbox is an environment and a working directory, not a container. It moves every path npm resolves from the environment into the lane and drops inherited variables that name the user’s home or this checkout; it does not stop a script that hard-codes an absolute path, and `PATH` is passed through so the child can find its own node. Writes outside the lane are therefore *detected* — the checkout’s `.git/hooks` and its top level are hashed before and after — and refused by name, not prevented.',
92		'The boundary reading watches two places: the top level of the checkout and `.git/hooks`. A write anywhere else outside the lane — a sibling directory, a deeper path in the checkout, another checkout on this host — is not observed here, and `writesOutsideLane: []` does not establish that none happened.',
93		'`closure: resolve` means the lane manifest declares a build toolchain the recorded lockfile predates, so npm resolved rather than replayed. The application’s own pins still come from the lockfile; what was newly resolved is what the manifest rewrite added, and that resolution is not a pin this repository recorded.',
94	]);
95	
96	function hostOf(value: string): string | null {
97		if (!value.startsWith('http://') && !value.startsWith('https://')) return null;
98		const parsed = parseURL(value);
99		return parsed.host ?? null;
100	}
101	
102	/** Read the two policy-bearing facts out of an npm lockfile. */
103	export function readLockfileFindings(
104		lockfile: string,
105		document: Record<string, unknown>,
106	): LockfileFindings {
107		const remote = new Set<string>();
108		const scripts = new Set<string>();
109		const lockfileVersion =
110			typeof document.lockfileVersion === 'number' ? document.lockfileVersion : 1;
111		const packages = document.packages as Record<string, unknown> | undefined;
112		if (packages !== undefined)
113			for (const key of Object.keys(packages).sort()) {
114				const entry = packages[key] as Record<string, unknown> | undefined;
115				if (entry === undefined || entry === null) continue;
116				const resolved = typeof entry.resolved === 'string' ? entry.resolved : null;
117				const host = resolved === null ? null : hostOf(resolved);
118				if (host !== null && host !== DEFAULT_REGISTRY_HOST)
119					remote.add(`${key === '' ? '.' : key} <- ${resolved ?? ''}`);
120				if (entry.hasInstallScript === true) scripts.add(key === '' ? '.' : key);
121			}
122		const walk = (tree: Record<string, unknown> | undefined, prefix: string): void => {
123			if (tree === undefined || tree === null) return;
124			for (const name of Object.keys(tree).sort()) {
125				const entry = tree[name] as Record<string, unknown> | undefined;
126				if (entry === undefined || entry === null) continue;
127				const identifier = prefix === '' ? name : `${prefix}/${name}`;
128				const version = typeof entry.version === 'string' ? entry.version : '';
129				const resolved = typeof entry.resolved === 'string' ? entry.resolved : version;
130				const host = hostOf(resolved);
131				if (host !== null && host !== DEFAULT_REGISTRY_HOST)
132					remote.add(`${identifier} <- ${resolved}`);
133				if (entry.hasInstallScript === true) scripts.add(identifier);
134				walk(entry.dependencies as Record<string, unknown> | undefined, identifier);
135			}
136		};
137		walk(document.dependencies as Record<string, unknown> | undefined, '');
138		return Object.freeze({
139			lockfile,
140			lockfileVersion,
141			remoteTarballDependencies: Object.freeze([...remote].sort()),
142			installScriptPackages: Object.freeze([...scripts].sort()),
143		});
144	}
145	
146	/**
147	 * Whether the closure is replayed or resolved.
148	 *
149	 * `replay` is `npm ci`: the lockfile is installed exactly as recorded, and a
150	 * manifest that disagrees with it is an error. `resolve` is `npm install`, and
151	 * it is what a lane whose manifest this pipeline rewrote requires — the lane
152	 * declares a build toolchain the recorded lockfile predates, so there is no
153	 * recorded closure for it to replay. The application's own pins still come from
154	 * the lockfile; what is newly resolved is what the rewrite added.
155	 */
156	export type ClosureMode = 'replay' | 'resolve';
157	
158	export type InstallPlan = Readonly<{
159		packageManager: string;
160		lockfile: string;
161		closure: ClosureMode;
162		findings: LockfileFindings;
163		policy: InstallPolicy;
164		command: readonly string[];
165	}>;
166	
167	/**
168	 * Decide the install command for a lane, or refuse by name.
169	 *
170	 * Nothing runs here. The whole point is that every decision this stage would
171	 * otherwise ask an operator for is taken from the declared policy and the
172	 * lockfile before a registry is contacted.
173	 */
174	export async function planLaneInstall(
175		laneDir: string,
176		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
177		environment: NodeJS.ProcessEnv = process.env,
178		closure: ClosureMode = 'replay',
179	): Promise<InstallPlan> {
180		if (policy.allowInstallScripts && policy.skipInstallScripts)
181			refuse({
182				code: 'install.install-script-policy-conflicts',
183				message:
184					'Install: the install-script allowance and the install-script skip were both declared. They are opposite policies and this flow does not pick between two declarations.',
185				stage: 'install',
186				origin: 'pipeline',
187			});
188		if (environment.VERSIONLESS_NETWORK_MODE === 'offline')
189			refuse({
190				code: 'install.network-not-permitted',
191				message:
192					'Install: VERSIONLESS_NETWORK_MODE is offline, so this stage may not reach a registry. No closure was resolved and nothing was installed.',
193				stage: 'install',
194				origin: 'pipeline',
195			});
196		/**
197		 * Which lockfiles the lane actually carries, read before anything is said
198		 * about them. The order matters, and it is the order a reader would want:
199		 * an npm lockfile is looked for first, so that "there is nothing to install
200		 * from" is only ever said about a lane where that is true.
201		 */
202		let lockfile: string | null = null;
203		for (const name of NPM_LOCKFILES)
204			if (lockfile === null && (await fileExists(path.join(laneDir, name)))) lockfile = name;
205		const foreign: string[] = [];
206		for (const name of Object.keys(FOREIGN_LOCKFILES).sort())
207			if (await fileExists(path.join(laneDir, name))) foreign.push(name);
208		/**
209		 * A lane pinned by another package manager *as well as* by npm. Both are
210		 * present, so this is not a lane missing a closure — it is a lane carrying
211		 * two, and the policies this stage holds are npm's.
212		 */
213		if (lockfile !== null && foreign.length > 0) {
214			const name = foreign[0] as string;
215			refuse({
216				code: 'install.package-manager-not-npm',
217				message: `Install: the lane carries ${name}, so its closure is pinned by ${FOREIGN_LOCKFILES[name] ?? 'another package manager'}. The two policies this stage carries — the remote-tarball allowance and the install-script allowance — are npm policies, and this flow does not translate them onto another package manager.`,
218				stage: 'install',
219				origin: 'pipeline',
220			});
221		}
222		/**
223		 * A lockfile is present and this stage does not read it. Saying `absent`
224		 * here would be false: the application pinned its closure, it pinned it
225		 * with a package manager whose lockfile this stage cannot read, and those
226		 * are different findings for an operator deciding what to do next.
227		 */
228		if (lockfile === null && foreign.length > 0)
229			refuse({
230				code: 'install.lockfile-foreign',
231				message: `Install: the lane carries ${foreign.join(', ')}, and this stage reads ${NPM_LOCKFILES.join(', ')}. The closure is pinned — by ${FOREIGN_LOCKFILES[foreign[0] as string] ?? 'another package manager'} — and it is pinned in a lockfile this flow does not read, so it is not absent and it is not installable here.`,
232				stage: 'install',
233				origin: 'pipeline',
234			});
235		if (lockfile === null)
236			refuse({
237				code: 'install.lockfile-absent',
238				message: `Install: the lane carries none of ${NPM_LOCKFILES.join(', ')}, so there is no pinned closure to install. This flow installs a recorded closure rather than resolving a new one.`,
239				stage: 'install',
240				origin: 'pipeline',
241			});
242		const document = await readJsonFile(path.join(laneDir, lockfile));
243		if (document === null)
244			refuse({
245				code: 'install.lockfile-unreadable',
246				message: `Install: ${lockfile} is not readable as a JSON object, so the closure it pins cannot be read and no install policy can be checked against it.`,
247				stage: 'install',
248				origin: 'pipeline',
249			});
250		const findings = readLockfileFindings(lockfile, document);
251		if (findings.remoteTarballDependencies.length > 0 && !policy.allowRemoteTarballs)
252			refuse({
253				code: 'install.remote-tarball-policy-not-declared',
254				message: `Install: the lockfile resolves ${String(findings.remoteTarballDependencies.length)} dependency(ies) from outside ${DEFAULT_REGISTRY_HOST}, first ${findings.remoteTarballDependencies[0] ?? ''}. Modern npm refuses those with EALLOWREMOTE unless the remote-tarball allowance is declared. Declare --allow-remote-tarballs to carry that policy; this flow does not take the allowance on an operator's behalf.`,
255				stage: 'install',
256				origin: 'pipeline',
257			});
258		if (
259			findings.installScriptPackages.length > 0 &&
260			!policy.allowInstallScripts &&
261			!policy.skipInstallScripts
262		)
263			refuse({
264				code: 'install.install-script-policy-not-declared',
265				message: `Install: the lockfile declares ${String(findings.installScriptPackages.length)} package(s) carrying an install script, first ${findings.installScriptPackages[0] ?? ''}. Modern npm skips them by default, which produces a tree whose native build was never attempted. Declare --allow-install-scripts to run them or --skip-install-scripts to record the skip as a decision; this flow does not let the default stand unnamed.`,
266				stage: 'install',
267				origin: 'pipeline',
268			});
269		const command = [
270			'npm',
271			closure === 'replay' ? 'ci' : 'install',
272			'--no-audit',
273			'--no-fund',
274			...(policy.allowRemoteTarballs ? ['--allow-remote', 'all'] : []),
275			...(policy.allowInstallScripts ? ['--foreground-scripts'] : ['--ignore-scripts']),
276			...(policy.allowPeerConflicts ? ['--legacy-peer-deps'] : []),
277		];
278		return Object.freeze({
279			packageManager: 'npm',
280			lockfile,
281			closure,
282			findings,
283			policy,
284			command: Object.freeze(command),
285		});
286	}
287	
288	/**
289	 * The lane-owned home an install child is given, relative to the lane.
290	 *
291	 * `--allow-install-scripts` is a policy about what may run, and until this
292	 * existed it was silently also a policy about where those scripts may write.
293	 * On 2026-08-10 an acquired application's `postinstall` — husky v4, out of
294	 * `.versionless/work/react-mycrypto/baseline/node_modules` — overwrote all 18
295	 * of this repository's own Git hooks and rewrote them to source a file it
296	 * created in `.git/hooks`. Nothing refused, nothing counted it, and the hooks
297	 * fired on every commit afterwards. They were inert only because `yarn` was
298	 * missing from `PATH`.
299	 */
300	export const INSTALL_HOME_DIRECTORY = '.install-home';
301	
302	/**
303	 * The variables kept verbatim even when they name the user's home.
304	 *
305	 * `PATH` is the honest exception and it is named rather than hidden: the node
306	 * and npm this stage runs are frequently installed under the invoking user's
307	 * home (nvm, volta, asdf), so filtering `PATH` for home references would leave
308	 * the child unable to find the binary it is supposed to be. Everything else
309	 * that points at the user's home or at this checkout is dropped.
310	 */
311	export const SANDBOX_KEPT_VARIABLES: readonly string[] = Object.freeze(['PATH']);
312	
313	export type InstallSandbox = Readonly<{
314		/** The lane-owned directory handed to the child as `HOME`. */
315		home: string;
316		/** Every directory created before the child runs. */
317		directories: readonly string[];
318		/** The exact environment the child is spawned with. */
319		environment: Readonly<Record<string, string>>;
320		/** Inherited variables dropped, and why they were dropped. */
321		strippedVariables: readonly string[];
322	}>;
323	
324	/** Whether `value` names `base` or anything under it. */
325	function referencesDirectory(value: string, base: string | null): boolean {
326		if (base === null || base.length < 2) return false;
327		return value === base || value.includes(base);
328	}
329	
330	/**
331	 * The environment an install child gets: lane-owned, and nothing borrowed.
332	 *
333	 * Every path npm writes to outside a project — its cache, its prefix, its two
334	 * config files, and the XDG directories a package's own script reads — is
335	 * pointed inside the lane, so the ordinary case of a script writing "to the
336	 * user's config" lands in a directory the lane owns and the run can throw away.
337	 * Then every inherited variable that names the user's home or this checkout is
338	 * dropped, so a script cannot read the escape route out of its own environment.
339	 */
340	export function planInstallSandbox(
341		laneDir: string,
342		environment: NodeJS.ProcessEnv,
343		boundaryRoot: string,
344	): InstallSandbox {
345		const lane = path.resolve(laneDir);
346		const home = path.join(lane, INSTALL_HOME_DIRECTORY);
347		const config = path.join(home, '.config');
348		const cache = path.join(home, '.cache');
349		const npmCache = path.join(home, 'npm-cache');
350		const prefix = path.join(home, 'npm-prefix');
351		const owned: Record<string, string> = {
352			HOME: home,
353			XDG_CONFIG_HOME: config,
354			XDG_CACHE_HOME: cache,
355			npm_config_cache: npmCache,
356			npm_config_prefix: prefix,
357			npm_config_userconfig: path.join(home, '.npmrc'),
358			npm_config_globalconfig: path.join(prefix, 'etc', 'npmrc'),
359		};
360		const inheritedHome =
361			typeof environment.HOME === 'string' && environment.HOME !== ''
362				? path.resolve(environment.HOME)
363				: null;
364		const root = path.resolve(boundaryRoot);
365		const stripped: string[] = [];
366		const passed: Record<string, string> = {};
367		for (const key of Object.keys(environment).sort()) {
368			const value = environment[key];
369			if (value === undefined) continue;
370			if (key in owned) {
371				stripped.push(`${key} (replaced with a lane-owned directory)`);
372				continue;
373			}
374			/** npm reads its configuration from `npm_config_*` case-insensitively. */
375			if (/^npm_config_/i.test(key)) {
376				stripped.push(`${key} (inherited npm configuration)`);
377				continue;
378			}
379			if (SANDBOX_KEPT_VARIABLES.includes(key)) {
380				passed[key] = value;
381				continue;
382			}
383			if (referencesDirectory(value, inheritedHome)) {
384				stripped.push(`${key} (names the invoking user's home)`);
385				continue;
386			}
387			if (referencesDirectory(value, root)) {
388				stripped.push(`${key} (names this checkout)`);
389				continue;
390			}
391			passed[key] = value;
392		}
393		return Object.freeze({
394			home,
395			directories: Object.freeze([home, config, cache, npmCache, prefix]),
396			environment: Object.freeze({ ...passed, ...owned }),
397			strippedVariables: Object.freeze(stripped),
398		});
399	}
400	
401	/** One digest per watched file, keyed by absolute path. */
402	export type BoundarySnapshot = ReadonlyMap<string, string>;
403	
404	async function hashIfReadable(file: string): Promise<string | null> {
405		try {
406			return sha256(await readFile(file));
407		} catch {
408			return null;
409		}
410	}
411	
412	async function hashTree(directory: string, into: Map<string, string>): Promise<void> {
413		let entries;
414		try {
415			entries = await readdir(directory, { withFileTypes: true });
416		} catch {
417			return;
418		}
419		for (const entry of entries) {
420			const full = path.join(directory, entry.name);
421			if (entry.isDirectory()) {
422				await hashTree(full, into);
423				continue;
424			}
425			if (!entry.isFile()) continue;
426			const digest = await hashIfReadable(full);
427			if (digest !== null) into.set(full, digest);
428		}
429	}
430	
431	/**
432	 * The surface an install child is not allowed to move, hashed.
433	 *
434	 * Two places, and both are chosen because a write there is executable rather
435	 * than merely untidy: the checkout's `.git/hooks`, which is what the husky
436	 * escape took, and the top level of the checkout, which is where a `postinstall`
437	 * that guesses at a project root lands. Neither is walked deeply, so the reading
438	 * is cheap enough to take on every install. Anything inside the lane is excluded
439	 * by construction: the lane is what the child is *for*.
440	 */
441	export async function snapshotInstallBoundary(
442		boundaryRoot: string,
443		laneDir: string,
444	): Promise<BoundarySnapshot> {
445		const root = path.resolve(boundaryRoot);
446		const lane = path.resolve(laneDir);
447		const snapshot = new Map<string, string>();
448		let entries;
449		try {
450			entries = await readdir(root, { withFileTypes: true });
451		} catch {
452			entries = [];
453		}
454		for (const entry of entries) {
455			if (!entry.isFile()) continue;
456			const digest = await hashIfReadable(path.join(root, entry.name));
457			if (digest !== null) snapshot.set(path.join(root, entry.name), digest);
458		}
459		await hashTree(path.join(root, '.git', 'hooks'), snapshot);
460		for (const file of [...snapshot.keys()])
461			if (file === lane || file.startsWith(`${lane}/`)) snapshot.delete(file);
462		return snapshot;
463	}
464	
465	/** Every watched path the child created, changed, or removed, named. */
466	export function boundaryWrites(
467		before: BoundarySnapshot,
468		after: BoundarySnapshot,
469		boundaryRoot: string,
470	): readonly string[] {
471		const root = path.resolve(boundaryRoot);
472		const name = (file: string): string => {
473			const relative = path.relative(root, file);
474			return relative === '' || relative.startsWith('..') ? file : relative;
475		};
476		const writes: string[] = [];
477		for (const [file, digest] of after)
478			if (before.get(file) !== digest)
479				writes.push(`${before.has(file) ? 'modified' : 'created'} ${name(file)}`);
480		for (const file of before.keys()) if (!after.has(file)) writes.push(`deleted ${name(file)}`);
481		return Object.freeze(writes.sort());
482	}
483	
484	export type InstallRecord = Readonly<{
485		stage: 'install';
486		ran: boolean;
487		/** Why the stage did not run, when it did not. */
488		reason: string | null;
489		packageManager: string | null;
490		lockfile: string | null;
491		closure: ClosureMode | null;
492		policy: InstallPolicy;
493		remoteTarballDependencies: readonly string[];
494		installScriptPackages: readonly string[];
495		command: readonly string[] | null;
496		exitCode: number | null;
497		/** Packages present in the lane's installed closure afterwards. */
498		installedPackages: number | null;
499		/** The lane-owned environment the install child was confined to. */
500		sandbox: Readonly<{
501			home: string | null;
502			strippedVariables: readonly string[];
503		}> | null;
504		/** What was watched outside the lane, and what moved there. */
505		boundary: Readonly<{
506			root: string;
507			pathsObservedBefore: number;
508			pathsObservedAfter: number;
509			writesOutsideLane: readonly string[];
510		}> | null;
511		notEstablished: readonly string[];
512	}>;
513	
514	/** The record for a stage the run did not ask for. */
515	export function installNotRequested(reason: string): InstallRecord {
516		return Object.freeze({
517			stage: 'install',
518			ran: false,
519			reason,
520			packageManager: null,
521			lockfile: null,
522			closure: null,
523			policy: DEFAULT_INSTALL_POLICY,
524			remoteTarballDependencies: Object.freeze([]),
525			installScriptPackages: Object.freeze([]),
526			command: null,
527			exitCode: null,
528			installedPackages: null,
529			sandbox: null,
530			boundary: null,
531			notEstablished: INSTALL_NOT_ESTABLISHED,
532		});
533	}
534	
535	/** How many packages the lane's installed closure carries, or null. */
536	export async function installedPackageCount(laneDir: string): Promise<number | null> {
537		const modules = path.join(laneDir, 'node_modules');
538		if (!(await directoryExists(modules))) return null;
539		let count = 0;
540		for (const entry of await readdir(modules, { withFileTypes: true })) {
541			if (!entry.isDirectory() || entry.name === '.bin') continue;
542			if (!entry.name.startsWith('@')) {
543				count += 1;
544				continue;
545			}
546			for (const scoped of await readdir(path.join(modules, entry.name), { withFileTypes: true }))
547				if (scoped.isDirectory()) count += 1;
548		}
549		return count;
550	}
551	
552	/**
553	 * Run the install this stage planned.
554	 *
555	 * A non-zero exit here is a **defect**, not a refusal: the policies were
556	 * declared, the closure was pinned, and the install still failed. Scoring that
557	 * as a refusal would let a broken tree be counted as a named, expected outcome.
558	 */
559	export async function runLaneInstall(
560		laneDir: string,
561		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
562		environment: NodeJS.ProcessEnv = process.env,
563		closure: ClosureMode = 'replay',
564		boundaryRoot: string = process.cwd(),
565	): Promise<InstallRecord> {
566		const plan = await planLaneInstall(laneDir, policy, environment, closure);
567		const sandbox = planInstallSandbox(laneDir, environment, boundaryRoot);
568		for (const directory of sandbox.directories) await mkdir(directory, { recursive: true });
569		const before = await snapshotInstallBoundary(boundaryRoot, laneDir);
570		const [binary, ...args] = plan.command as readonly [string, ...string[]];
571		let failure: unknown = null;
572		try {
573			await run(binary, args, {
574				cwd: laneDir,
575				env: sandbox.environment,
576				maxBuffer: 64 * 1024 * 1024,
577			});
578		} catch (error) {
579			failure = error;
580		}
581		/**
582		 * The boundary is read before the exit code is, and it decides first.
583		 *
584		 * A script that wrote into the checkout and then failed is not a broken
585		 * install that happens to have had a side effect; it is the side effect,
586		 * and reporting the exit code instead would bury the only fact an operator
587		 * needs. So the escape is named whether the install succeeded or not.
588		 */
589		const after = await snapshotInstallBoundary(boundaryRoot, laneDir);
590		const writes = boundaryWrites(before, after, boundaryRoot);
591		if (writes.length > 0)
592			refuse({
593				code: 'install.script-wrote-outside-lane',
594				message: `Install: the closure's install scripts wrote outside the lane. ${String(writes.length)} watched path(s) under ${path.resolve(boundaryRoot)} moved while \`${plan.command.join(' ')}\` ran: ${writes.join('; ')}. The install ran with the install-script allowance, which permits a package's own build to run inside the lane; it does not permit it to write into the checkout that acquired it. The child was given a lane-owned HOME and a lane cwd, so this write reached the checkout by naming it rather than by inheriting it. The lane is not accepted as installed and the paths above are left as they are, so an operator can read what was attempted.`,
595				stage: 'install',
596				origin: 'pipeline',
597			});
598		if (failure !== null) {
599			const error = failure;
600			const detail = error instanceof Error ? error.message : String(error);
601			/**
602			 * One npm failure is a policy question rather than a breakage: a peer
603			 * conflict is npm reporting that the closure it was asked for is not
604			 * one it will assemble by default. That is a decision, so it is a named
605			 * refusal an operator can count and answer with a flag. Every other
606			 * failure is a defect.
607			 */
608			if (detail.includes('ERESOLVE') && !policy.allowPeerConflicts)
609				refuse({
610					code: 'install.peer-resolution-policy-not-declared',
611					message: `Install: npm refused the lane closure with ERESOLVE — a peer dependency conflict between the application's own era pins and the build toolchain the lane now declares. Declare --allow-peer-conflicts to install through it, which is a decision about what the lane's closure may be, or change what the lane declares. This flow does not take that decision on an operator's behalf.`,
612					stage: 'install',
613					origin: 'pipeline',
614				});
615			throw new Error(
616				`install: ${plan.command.join(' ')} failed in the lane. This is a defect rather than a refusal: the declared policies were applied and the pinned closure still did not install. ${detail}`,
617			);
618		}
619		return Object.freeze({
620			stage: 'install',
621			ran: true,
622			reason: null,
623			packageManager: plan.packageManager,
624			lockfile: plan.lockfile,
625			closure: plan.closure,
626			policy,
627			remoteTarballDependencies: plan.findings.remoteTarballDependencies,
628			installScriptPackages: plan.findings.installScriptPackages,
629			command: plan.command,
630			exitCode: 0,
631			installedPackages: await installedPackageCount(laneDir),
632			sandbox: Object.freeze({
633				home: sandbox.home,
634				strippedVariables: sandbox.strippedVariables,
635			}),
636			boundary: Object.freeze({
637				root: path.resolve(boundaryRoot),
638				pathsObservedBefore: before.size,
639				pathsObservedAfter: after.size,
640				writesOutsideLane: writes,
641			}),
642			notEstablished: INSTALL_NOT_ESTABLISHED,
643		});
644	}
645

